<!doctype html><html><head><meta charset="utf-8"><title>{{ $d->number }}</title><style>body{font-family:DejaVu Sans,sans-serif;font-size:11px;color:#243342}h1{font-size:24px}table{width:100%;border-collapse:collapse;margin:18px 0}th,td{padding:10px;border-bottom:1px solid #ddd;text-align:left}p{white-space:pre-line;line-height:1.6}.right{text-align:right}.logo{max-height:60px;max-width:160px}</style></head><body>@if($logo)<img class="logo" src="{{ $logo }}">@endif<h2>{{ $d->business->name }}</h2><p>{{ $d->business->address }}<br>{{ $d->business->email }} · {{ $d->business->phone }}</p><h1>{{ $d->kind==='quotation'?'QUOTATION':'DELIVERY NOTE' }}</h1><p>{{ $d->number }} · {{ strtoupper($d->status) }}<br>Issued: {{ $d->issue_date->format('d M Y') }}<br>{{ $d->kind==='quotation'?'Valid until':'Delivery date' }}: {{ $d->due_date->format('d M Y') }}</p><h2>{{ $d->client->name }}</h2><p>{{ $d->client->company }}<br>{{ $d->delivery_address ?: $d->client->address }}</p><table><thead><tr><th>Description</th><th>Qty</th><th>Unit</th>@if($d->kind==='quotation')<th>Rate</th><th>Amount</th>@endif</tr></thead><tbody>@foreach($d->items as $i)<tr><td>{{ $i->description }}</td><td>{{ $i->quantity }}</td><td>{{ $i->unit }}</td>@if($d->kind==='quotation')<td>{{ app(\App\Services\CurrencyService::class)->format($i->unit_price_kobo,$d->currency,$d->currency_minor_units) }}</td><td>{{ app(\App\Services\CurrencyService::class)->format($i->line_total_kobo,$d->currency,$d->currency_minor_units) }}</td>@endif</tr>@endforeach</tbody></table>@if($d->kind==='quotation')@foreach(['Subtotal'=>'subtotal_kobo','Discount'=>'discount_kobo','Tax'=>'tax_kobo','Total'=>'total_kobo'] as $label=>$field)<p class="right">{{ $label }}: {{ app(\App\Services\CurrencyService::class)->format($d->$field,$d->currency,$d->currency_minor_units) }}</p>@endforeach<p>This quotation is not an invoice or payment receipt.</p>@else<p>Received by: {{ $d->received_by ?: '____________________________' }}<br>Signature: ____________________________<br>Date: ____________________________</p><p>This note records delivery quantities. It is not a payment receipt.</p>@endif<p>{{ $d->notes }}</p><p>{{ $d->terms }}</p></body></html>
